/**
 * O globo terrestre em 2D — a base das duas cenas que mostram a Terra
 * (`terra3d.ts` e `terra-criacao.ts`).
 *
 * No legado essas duas cenas eram esferas de Three.js com uma textura
 * equirretangular pintada num canvas. A base 3D do monorepo é uma projeção sobre
 * PixiJS e desenha esferas de cor sólida — ela não mapeia textura, e não vale
 * ganhar um pipeline de textura por causa de dois módulos.
 *
 * A saída é a mesma, porque o problema é mais simples do que parece: a Terra é
 * vista de uma direção só. Cada mancha de continente tem uma longitude e uma
 * latitude; girar o planeta é somar um ângulo à longitude; o que passa para trás
 * some; e o que fica de frente é achatado na horizontal por `cos(longitude)` —
 * que é exatamente o que a esfera faz com o desenho. Some a isso o sombreado do
 * terminador e o resultado lê como planeta.
 */

import { paleta } from './desenho.ts';

/** Uma mancha na superfície: longitude e latitude em graus, raios em fração. */
export interface Mancha {
  /** −180 a 180; cresce para leste. */
  readonly lon: number;
  /** −90 a 90; cresce para o norte. */
  readonly lat: number;
  /** Semi-eixos, em fração do raio do globo. */
  readonly rx: number;
  readonly ry: number;
  readonly cor: string;
}

