export interface OpcoesGlobo {
  /** Quanto o planeta já girou, em graus. */
  readonly giro: number;
  /** Cor do oceano no equador e nos polos. */
  readonly oceano?: readonly [string, string];
  /** Manchas a pintar sobre o oceano, em ordem. */
  readonly manchas?: readonly Mancha[];
  /** Opacidade das manchas — o manto de vapor a usa para abrir e fechar. */
  readonly opacidade?: number;
  /** Calotas polares. */
  readonly calotas?: boolean;
  /** 0 apaga o planeta, 1 é pleno dia. */
  readonly luz?: number;
  /** Halo de atmosfera em volta. */
  readonly atmosfera?: boolean;
}

/**
 * Desenha o globo em (cx, cy) com raio R. As manchas são recortadas pelo disco,
 * então nada escapa da borda.
 */
export function globo(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  R: number,
  opcoes: OpcoesGlobo,
): void {
  const cor = paleta();
  const luz = opcoes.luz ?? 1;
  const [equador, polo] = opcoes.oceano ?? ['#1b86dc', '#0a2c5c'];

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.clip();

  // O oceano: safira nos polos, turquesa no equador.
  const agua = ctx.createLinearGradient(0, cy - R, 0, cy + R);
  agua.addColorStop(0, polo);
  agua.addColorStop(0.5, equador);
  agua.addColorStop(1, polo);
  ctx.fillStyle = agua;
  ctx.fillRect(cx - R, cy - R, R * 2, R * 2);

  if (opcoes.calotas === true) {
    ctx.fillStyle = '#eef5ff';
    ctx.fillRect(cx - R, cy - R, R * 2, R * 0.16);
    ctx.fillRect(cx - R, cy + R * 0.84, R * 2, R * 0.16);
  }

  ctx.globalAlpha = opcoes.opacidade ?? 1;
  for (const mancha of opcoes.manchas ?? []) {
    // Longitude relativa à face voltada para quem olha.
    const lon = ((((mancha.lon + opcoes.giro + 180) % 360) + 360) % 360) - 180;
    const rad = (lon * Math.PI) / 180;
    // Fora de ±90° a mancha está do outro lado do planeta.
    if (Math.abs(lon) > 88) continue;

    const latRad = (mancha.lat * Math.PI) / 180;
    const x = cx + Math.sin(rad) * Math.cos(latRad) * R;
    const y = cy - Math.sin(latRad) * R;

    // O achatamento é o que dá a curvatura: quem está na borda vira um risco.
    const escalaX = Math.cos(rad);
    const escalaY = Math.cos(latRad) * 0.6 + 0.4;

    ctx.fillStyle = mancha.cor;
    ctx.beginPath();
    ctx.ellipse(x, y, mancha.rx * R * escalaX, mancha.ry * R * escalaY, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // O terminador: a luz vem de cima e da direita, como o sol da cena.
  const sombra = ctx.createRadialGradient(cx + R * 0.35, cy - R * 0.3, R * 0.1, cx, cy, R * 1.25);
  sombra.addColorStop(0, `rgb(0 0 0 / ${(1 - luz) * 45}%)`);
  sombra.addColorStop(1, `rgb(0 0 0 / ${25 + (1 - luz) * 60}%)`);
  ctx.fillStyle = sombra;
  ctx.fillRect(cx - R, cy - R, R * 2, R * 2);

  ctx.restore();

  if (opcoes.atmosfera === true) {
    const halo = ctx.createRadialGradient(cx, cy, R * 0.95, cx, cy, R * 1.14);
    halo.addColorStop(0, 'rgb(90 166 255 / 42%)');
    halo.addColorStop(1, 'rgb(90 166 255 / 0%)');
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(cx, cy, R * 1.14, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.strokeStyle = cor.trilho;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.stroke();
}
